37	// Utility class for safely allocating POD data. This is useful for avoiding
38	// leaks in cases where op params are allocated but fail to propagate to the
39	// parsed op data (e.g., when model parameters are invalid).
40	class SafeBuiltinDataAllocator {
41	 public:
42	  class BuiltinDataDeleter {
43	   public:
44	    explicit BuiltinDataDeleter(BuiltinDataAllocator* allocator)
45	        : allocator_(allocator) {}
46	
47	    void operator()(void* data) { allocator_->Deallocate(data); }
48	
49	   private:
50	    BuiltinDataAllocator* allocator_;
51	  };
52	
53	  template <typename T>
54	  using BuiltinDataPtr = std::unique_ptr<T, BuiltinDataDeleter>;
55	
56	  explicit SafeBuiltinDataAllocator(BuiltinDataAllocator* allocator)
57	      : allocator_(allocator) {}
58	
59	  template <typename T>
60	  BuiltinDataPtr<T> Allocate() {
61	    return BuiltinDataPtr<T>(allocator_->AllocatePOD<T>(),
62	                             BuiltinDataDeleter(allocator_));
63	  }
64	
65	 private:
66	  BuiltinDataAllocator* allocator_;
67	};
