80	// Copies the contents from the flatbuffer int vector `flatbuffer` into the
81	// int array `buffer`. `flat_vector` and `buffer` represent the same
82	// configuration operation for a given operation.
83	template <typename DataType = int32_t>
84	static TfLiteStatus FlatBufferIntVectorToArray(
85	    int max_size_of_buffer, const flatbuffers::Vector<DataType>* flat_vector,
86	    DataType* buffer, ErrorReporter* error_reporter, const char* op_name) {
87	  if (!flat_vector) {
88	    TF_LITE_REPORT_ERROR(error_reporter,
89	                         "Input array not provided for operation '%s'.\n",
90	                         op_name);
91	    return kTfLiteError;
92	  } else {
93	    size_t num_dimensions = flat_vector->size();
94	    if (num_dimensions > max_size_of_buffer / sizeof(DataType)) {
95	      TF_LITE_REPORT_ERROR(
96	          error_reporter,
97	          "Found too many dimensions in the input array of operation '%s'.\n",
98	          op_name);
99	      return kTfLiteError;
100	    } else {
101	      for (size_t i = 0; i < num_dimensions; ++i) {
102	        buffer[i] = flat_vector->Get(i);
103	      }
104	    }
105	  }
106	  return kTfLiteOk;
107	}
