25	TfLiteStatus GetRegistrationFromOpCode(
26	    const OperatorCode* opcode, const OpResolver& op_resolver,
27	    ErrorReporter* error_reporter, const TfLiteRegistration** registration) {
28	  TfLiteStatus status = kTfLiteOk;
29	  *registration = nullptr;
30	  auto builtin_code = GetBuiltinCode(opcode);
31	  int version = opcode->version();
32	
33	  if (builtin_code > BuiltinOperator_MAX) {
34	    TF_LITE_REPORT_ERROR(
35	        error_reporter,
36	        "Op builtin_code out of range: %d. Are you using old TFLite binary "
37	        "with newer model?",
38	        builtin_code);
39	    status = kTfLiteError;
40	  } else if (builtin_code != BuiltinOperator_CUSTOM) {
41	    *registration = op_resolver.FindOp(builtin_code, version);
42	    if (*registration == nullptr) {
43	      TF_LITE_REPORT_ERROR(
44	          error_reporter,
45	          "Didn't find op for builtin opcode '%s' version '%d'. "
46	          "An older version of this builtin might be supported. "
